"""Revelations三段逐字作者表达式，经真实POD/生产方法转到原生调用边界。"""
import unittest
from .test_api400_params import run_main
MAIN='\n#include "interfaces/lua/api400_params.hpp"\n#include "lua_object_handles.hpp"\n#include "interfaces/lua/api400_params.guards.hpp"\n#include "interfaces/lua/api400_fields.guards.hpp"\n#include "interfaces/lua/entity_lifetime.hpp"\n#include "infrastructure/call/engine_call_access.hpp"\n#include <cstdio>\n#include <cstring>\n#include <cassert>\n#include "interfaces/lua/vector_api.hpp"\nextern "C" {\n#include <lauxlib.h>\n#include <lualib.h>\n}\nusing namespace isaac::runtime;using Vec=LuaRuntime::VectorHandle;\n\nstatic unsigned rngCalls{},fireCalls{},bossCalls{};\nstatic std::uint32_t Random(){++rngCalls;return 0x80000000U;}\ntemplate<class T>T At(const void*p,unsigned o){T value{};std::memcpy(&value,static_cast<const char*>(p)+o,sizeof(value));return value;}\nstatic std::uintptr_t Fire(void*self,const Vec*pos,const Vec*velocity,std::int32_t mode,const void*p){assert(self==g_Entities[kEnemyA].data()&&pos->x==10&&pos->y==20);++fireCalls;\nif(mode==7){assert(velocity->x==8&&velocity->y==0&&At<float>(p,0x14)==.6F&&At<float>(p,0x24)==-3&&At<float>(p,0x10)==.9F&&At<std::int32_t>(p,0x94)==2&&At<float>(p,0x2c+12)==.5F);}\nelse{assert(mode==0&&velocity->x==3&&velocity->y==4&&At<float>(p,4)==11.25F&&At<float>(p,8)==-2.5F&&At<float>(p,12)==.125F&&At<std::uint64_t>(p,0x58)==1&&At<float>(p,0x1c)==2.5F);}\nreturn AddressOf(g_Entities[kBullet]);}\nstatic std::uintptr_t Boss(void*self,std::int32_t count,const Vec*target,float trajectory,const void*p){assert(self==g_Entities[kEnemyA].data()&&count==8&&target->x==0&&target->y==0&&trajectory==10&&At<float>(p,0x10)==.5F&&At<float>(p,0x3c)==.7F&&At<float>(p,0x40)==.7F&&At<float>(p,0x44)==.75F&&At<float>(p,0x48)==1);++bossCalls;return AddressOf(g_Entities[kBullet]);}\nint main(){static_cast<void>(kScriptTemplate);static_cast<void>(&HarnessHasCollectible);static_cast<void>(&BuildPrelude);static_cast<void>(&ExpectNumber);CreateBlocks();FillEntities();WriteWord(g_Entities[kEnemyA],0,g_EngineBase+kEntityNpcVtableOffset);WriteWord(g_Entities[kBullet],0,g_EngineBase+kEntityProjectileVtableOffset);PublishLists();PublishGame();PublishEntityList(g_RoomBytes,true);LuaRuntime::SetEngineModuleBase(g_EngineBase);LuaRuntime::SetGameBindings(g_EngineBase+kGameOwnerGlobalSlotOffset,0x2222);\nnamespace G=api400_params;\nstd::memcpy(g_ModuleBytes.data()+G::kRandomU32Entry,G::kRandomU32Guard.data(),16);std::memcpy(g_ModuleBytes.data()+G::kFireProjectilesEntry,G::kFireProjectilesGuard.data(),16);std::memcpy(g_ModuleBytes.data()+G::kFireBossProjectilesEntry,G::kFireBossProjectilesGuard.data(),16);std::memcpy(g_ModuleBytes.data()+api400_fields::kProjectileEntry,api400_fields::kProjectileGuard.data(),16);\nSetApi400ParamsNativeTestBindings({{engine_call::AddressOfFunction(&Random),engine_call::AddressOfFunction(&Fire),engine_call::AddressOfFunction(&Boss)}});\nconst char*script=R"AUTHOR(local npc=Isaac.FindByType(20)[1]:ToNPC();assert(npc);local ProjectilesMode=(function()\nreturn {\n    SINGLE_PROJ = 0, -- single projectile\n    TWO_PROJ =1, -- two projectiles (uses params.Spread)\n    THREE_PROJ = 2, -- three projectiles (uses params.Spread)\n    THREE_PROJ_ALT = 3, -- three projectiles (uses params.Spread, more spread out?)\n    FOUR_PROJ = 4, -- four projectiles (uses params.Spread)\n    FIVE_PROJ = 5, -- five projectiles (uses params.Spread)\n    PLUS = 6, -- four projectiles in a + pattern (uses velocity.x as speed)\n    CROSS = 7, -- four projectiles in a x pattern (uses velocity.x as speed)\n    STAR = 8, -- eight projectiles in a star pattern (uses velocity.x as speed)\n    CIRCLE = 9, -- N projectiles in a circle (velocity.x = speed, velocity.y = N, params.FireDirectionLimit and params.DotProductLimit to fire in an arc only)\n}\nend)();\nfunction SetBit(x, p)\n    if not x or not p then\n        error("HasBit | x or p nil: " .. tostring(x) .. ":" .. tostring(p), 2)\n    end\n    return x | p\nend\ndo local fire={Position=Vector(10,20)}\nlocal pos = fire.Position\n                        local speed = 8\n                        local mode = ProjectilesMode.CROSS\n                        local params = ProjectileParams()\n                        params.VelocityMulti = 0.9\n                        params.Variant = ProjectileVariant.PROJECTILE_FIRE\n                        params.Color = Color(1, 0.7, 1, 0.5)\n                        params.Scale = 0.6\n                        params.Acceleration = -3\n                            \n                        npc:FireProjectiles(pos, Vector(speed, 0), mode, params)\nend\ndo\nlocal tarParams = ProjectileParams()\n                    local tarColor = Color(1, 1, 1, 1)\n                    tarColor:SetColorize(0.7,0.7,0.75,1)\n                    tarParams.Color = tarColor\n                    tarParams.VelocityMulti = 0.5\n                    npc:FireBossProjectiles(8, Vector.Zero, 10, tarParams)\nend\ndo local pos=Vector(10,20);local vel=Vector(3,4);local data={Phase=2,bal={ShootHeightMod=11.25,ShootFallingSpeedMod=-2.5,ShootFallingAccelMod=.125,HomingStrength=2.5}};local blood={};local PurpleShootColor=Color(1,0,1,1);local BloodShootColor=Color(1,0,0,1)\nlocal projParams = ProjectileParams()\n            projParams.HeightModifier = data.bal.ShootHeightMod\n            projParams.FallingSpeedModifier = data.bal.ShootFallingSpeedMod\n            projParams.FallingAccelModifier = data.bal.ShootFallingAccelMod\n\n            if data.Phase == 2 then\n                projParams.BulletFlags = SetBit(projParams.BulletFlags, ProjectileFlags.SMART)\n                projParams.HomingStrength = data.bal.HomingStrength\n                blood.Color = PurpleShootColor\n            else\n                blood.Color = BloodShootColor\n            end\n\n            npc:FireProjectiles(pos, vel, ProjectilesMode.SINGLE_PROJ, projParams)\nend\n)AUTHOR";if(LuaRuntime::InitializeFromBuffer(script,std::strlen(script),"@api400-author.lua")!=LuaRuntime::LuaInitResult::Success){LuaRuntime::LuaErrorHistoryEntryView errors[8]{};const auto n=LuaRuntime::CopyLuaErrorHistory(errors,8);for(std::size_t i=0;i<n;++i)std::fprintf(stderr,"%s\\n",errors[i].text);return 1;}assert(rngCalls==3&&fireCalls==2&&bossCalls==1);return 0;}\n'
class CommunityReplay(unittest.TestCase):
 def test_original_author_expressions(self):
  r=run_main(MAIN);self.assertEqual(r.returncode,0,r.stdout+r.stderr)
